import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create the plane geometry (card-sized, horizontal row)
  const geometry = new THREE.PlaneGeometry(3.2, 0.5);

  // Load the brushed metal texture
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 1,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 0.7, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Load and apply the brushed metal texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.color.setHex(0xffffff);
      material.map = texture;
      material.needsUpdate = true;
    });
  }

  // Create a subtle divider line at the bottom edge
  const dividerGeometry = new THREE.PlaneGeometry(3.2, 0.01);
  const dividerMaterial = new MeshBasicNodeMaterial({
    color: 0xe8ecf2,
    transparent: true,
    opacity: 0.15,
  });
  const divider = new THREE.Mesh(dividerGeometry, dividerMaterial);
  divider.position.z = 0.01;
  divider.position.y = -0.25;
  mesh.add(divider);

  // Store timelines for cleanup
  const timelines = [];

  // Hover effect: rise-in (subtle lift)
  const onHover = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    const tl = gsap.to(mesh.position, {
      y: 0.7 + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  const onHoverOut = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    const tl = gsap.to(mesh.position, {
      y: 0.7,
      duration: 0.5,
      ease: 'power2.out',
    });
    timelines.push(tl);
  };

  // Click effect: press-down + emit event
  const onClick = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    const tl = gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(mesh.scale, {
          x: 1,
          y: 1,
          duration: 0.2,
          ease: 'power2.out',
        });
      },
    });
    timelines.push(tl);
    ctx.emit('hub-collection.select', { itemId: config.itemId });
  };

  // Attach event handlers to userData
  mesh.userData.handlers = {
    onHover,
    onHoverOut,
    onClick,
  };

  // Cleanup function
  mesh.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
    dividerGeometry.dispose();
    dividerMaterial.dispose();
  };

  return mesh;
}
